import{_ as e,o,c as a,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"1998年 · 大象难寻与会计之殇","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1998年.md","filePath":"05_quotes/by-year/1998年.md"}'),l={name:"05_quotes/by-year/1998年.md"};function u(q,t,c,s,_,p){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_1998年-·-大象难寻与会计之殇" tabindex="-1">1998年 · 大象难寻与会计之殇 <a class="header-anchor" href="#_1998年-·-大象难寻与会计之殇" aria-label="Permalink to &quot;1998年 · 大象难寻与会计之殇&quot;">​</a></h1><blockquote><p>&quot;我们现在需要&#39;大象&#39;才能获得显著收益——而大象很难找。当我们在寻找大象时，请放心，我们将继续专注于这场狩猎。无论未来如何，我向你做出一个承诺：只要我还在，我将至少保持99%的净值在伯克希尔。&quot;——巴菲特（68岁）</p></blockquote><p>本页收录1998年致股东信中的经典语录。巴菲特在这一年完成了两大历史性收购——通用再保险和NetJets，同时对华尔街盛行的期权文化和重组会计发起了尖锐批评。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;当管理层在采用他认为投资者会喜欢的&#39;调整后&#39;数字时，期望他们会诚实地呈现所有费用，这是对人性要求太多了。当这种行为成为常态时，投资者被欺骗的不仅是数字，而是他们据此做出判断的基础本身。&quot;</p></blockquote><blockquote><p>&quot;公司治理评论者很少区分上市公司中存在的三种根本不同的管理者/所有者情形：第一种，公司没有控股股东；第二种，控股股东同时也是管理者；第三种，存在不参与管理的控股股东的情形。&quot;</p></blockquote><blockquote><p>&quot;如果CEO对一个特别愚蠢的收购感到热情，他的内部员工和外部顾问都会提出任何需要的预测来证明他的立场。只有在童话故事中，皇帝才会被告知他们是裸体的。&quot;</p></blockquote><blockquote><p>&quot;查理和我近年来对期权所做的收益调整，经常将报告的每股数据削减5%，10%也并非罕见。有时下调幅度大到影响了我们的投资组合决策，导致我们不得不抛售或放弃本可能进行的股票购买。&quot;</p></blockquote><blockquote><p>&quot;在伯克希尔哈撒韦，我们希望制定既易于理解又与我们希望员工实现的目标同步的薪酬政策。写作新业务是昂贵的。如果我们要在奖金计算中包括这些成本，我们就是在惩罚我们的员工获取新保单，即使这些非常符合伯克希尔的利益。&quot;</p></blockquote><blockquote><p>&quot;GEICO在纽约州的投诉比率不仅低于五大汽车保险公司中的其他四家，而且不到其他四家平均值的一半。&quot;</p></blockquote><blockquote><p>&quot;我们再次承诺，我们的个人净资产将继续高度集中在伯克希尔的股票上：我们不会要求您投资我们，然后把我们的钱放在别处。&quot;</p></blockquote><blockquote><p>&quot;在高尔夫比赛中，你应该将坏的分数计入你的总分——而不是建立一个&#39;准备金&#39;账户来吸收未来的失误，然后在情况好转时释放出来。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1998年伯克希尔净资产增长259亿美元（48.3%），主要来自收购中发行的股份。同年以220亿美元收购通用再保险，成为全球最大再保险集团之一。同时以7.25亿美元收购公务机公司NetJets的控股股权。该公司是全球公务机分时拥有模式的开创者和领导者，拥有超过160架飞机和千余名客户。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/1998年/翻译">01_letters/1998年/翻译</a> · <a href="/01_letters/1998年/核心总结">01_letters/1998年/核心总结</a> · <a href="/01_letters/1998年/思维导图">01_letters/1998年/思维导图</a>---</p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1998年/翻译">/01_letters/1998年/翻译</a></li></ul>',21)])])}const b=e(l,[["render",u]]);export{i as __pageData,b as default};
